//! Source image decoding/normalization, ICC profile management, forward sRGB -> CMYK
//! conversion, and soft-proofing preview generation.

use crate::adjustment::{AdjustmentParams, apply_adjustments};
use image::ImageDecoder;
use std::io::{BufRead, Cursor, Seek};
use std::sync::Arc;

/// Temporary CPU-bound pixel buffer generated by background worker threads
/// containing raw sRGB RGBA pixels restored for display preview simulation.
pub struct RawPreview {
    /// Width of the image in pixels.
    pub width: usize,
    /// Height of the image in pixels.
    pub height: usize,
    /// Standard sRGB RGBA interleaved pixel bytes.
    pub rgba: Vec<u8>,
}

/// Cached downscaled source sRGB image kept in memory to avoid repeating disk I/O
/// and Lanczos3 resampling during interactive slider adjustments.
#[derive(Clone)]
pub struct CachedImage {
    pub path: String,
    pub width: usize,
    pub height: usize,
    pub rgba: Arc<Vec<u8>>,
}

/// Cached target CMYK ICC profile bytes kept in memory after validation.
#[derive(Clone)]
pub struct CachedIcc {
    pub path: String,
    pub bytes: Arc<Vec<u8>>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum RenderingIntent {
    Perceptual,
    Relative,
    Saturation,
    Absolute,
}

impl RenderingIntent {
    /// Returns the active slice of all 4 ICC rendering intents.
    pub const ALL: [Self; 4] = [
        Self::Perceptual,
        Self::Relative,
        Self::Saturation,
        Self::Absolute,
    ];

    /// Maps to the `lcms2::Intent` enum.
    pub fn to_lcms2(self) -> lcms2::Intent {
        match self {
            Self::Perceptual => lcms2::Intent::Perceptual,
            Self::Relative => lcms2::Intent::RelativeColorimetric,
            Self::Saturation => lcms2::Intent::Saturation,
            Self::Absolute => lcms2::Intent::AbsoluteColorimetric,
        }
    }

    /// Maps to the display index in the `preview_buffers` array:
    /// `[0: Original, 1: Perceptual, 2: Relative, 3: Saturation, 4: Absolute]`.
    pub fn to_index(self) -> usize {
        match self {
            Self::Perceptual => 1,
            Self::Relative => 2,
            Self::Saturation => 3,
            Self::Absolute => 4,
        }
    }

    /// Creates a `RenderingIntent` from its display index (`1..=4`).
    pub fn from_index(index: usize) -> Option<Self> {
        match index {
            1 => Some(Self::Perceptual),
            2 => Some(Self::Relative),
            3 => Some(Self::Saturation),
            4 => Some(Self::Absolute),
            _ => None,
        }
    }

    /// Returns the filename suffix used for exported CMYK PSD files.
    pub fn suffix(self) -> &'static str {
        match self {
            Self::Perceptual => "perceptual",
            Self::Relative => "relative",
            Self::Saturation => "saturation",
            Self::Absolute => "absolute",
        }
    }
}

#[derive(Debug, Clone)]
pub enum AppError {
    ImageOpenError(String),
    InvalidImageDimensions(u32, u32),
    ProfileReadError(String),
    ProfileParseError(String),
    NotCmykProfile,
    TransformCreationError(String),
}

impl std::fmt::Display for AppError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::ImageOpenError(msg) => write!(f, "元画像の読み込みに失敗しました: {}", msg),
            Self::InvalidImageDimensions(w, h) => write!(
                f,
                "画像サイズ ({}x{}) がPSD形式の有効範囲 (1〜{}px) を超えています。",
                w,
                h,
                crate::psd::PSD_MAX_DIMENSION
            ),
            Self::ProfileReadError(msg) => {
                write!(f, "カラープロファイルの読み込みに失敗しました: {}", msg)
            }
            Self::ProfileParseError(msg) => {
                write!(f, "カラープロファイルの解析に失敗しました: {}", msg)
            }
            Self::NotCmykProfile => write!(f, "選択されたプロファイルはCMYK色空間ではありません。"),
            Self::TransformCreationError(msg) => write!(f, "変換処理の作成に失敗しました: {}", msg),
        }
    }
}

impl std::error::Error for AppError {}

const PREVIEW_MAX_DIMENSION: u32 = 1600;

/// Builds thread-safe `lcms2::Flags<DisallowCache>` with high-resolution LUT precalculation
/// and optional Black Point Compensation (BPC).
#[inline]
pub fn cmm_transform_flags(black_point_compensation: bool) -> lcms2::Flags<lcms2::DisallowCache> {
    let base = lcms2::Flags::NO_CACHE | lcms2::Flags::HIGHRES_PRECALC;
    if black_point_compensation {
        base | lcms2::Flags::BLACKPOINT_COMPENSATION
    } else {
        base
    }
}

/// Composites any transparent or semi-transparent RGBA pixels onto opaque paper white `(255, 255, 255, 255)`
/// so that flat PSD export and soft-proofing never expose unpremultiplied black/garbage background colors.
pub fn composite_over_white(rgba: &mut [u8]) {
    if rgba.chunks_exact(4).all(|px| px[3] == 255) {
        return;
    }

    for px in rgba.chunks_exact_mut(4) {
        let a = px[3];
        if a == 0 {
            px.copy_from_slice(&[255, 255, 255, 255]);
        } else if a < 255 {
            let a_u32 = a as u32;
            let inv_a = 255 - a_u32;
            px[0] = ((px[0] as u32 * a_u32 + 255 * inv_a + 127) / 255) as u8;
            px[1] = ((px[1] as u32 * a_u32 + 255 * inv_a + 127) / 255) as u8;
            px[2] = ((px[2] as u32 * a_u32 + 255 * inv_a + 127) / 255) as u8;
            px[3] = 255;
        }
    }
}

/// Converts RGBA8 pixels tagged with an embedded RGB ICC profile into standard sRGB in-place,
/// preserving the original alpha channel of each pixel.
pub fn convert_embedded_icc_to_srgb(rgba: &mut [u8], icc_bytes: &[u8]) {
    let Ok(src_profile) = lcms2::Profile::new_icc(icc_bytes) else {
        return;
    };
    if src_profile.color_space() != lcms2::ColorSpaceSignature::RgbData {
        return;
    }

    let srgb_profile = lcms2::Profile::new_srgb();
    let Ok(transform) = lcms2::Transform::new_flags_context(
        lcms2::GlobalContext::new(),
        &src_profile,
        lcms2::PixelFormat::RGBA_8,
        &srgb_profile,
        lcms2::PixelFormat::RGBA_8,
        lcms2::Intent::RelativeColorimetric,
        lcms2::Flags::NO_CACHE
            | lcms2::Flags::HIGHRES_PRECALC
            | lcms2::Flags::BLACKPOINT_COMPENSATION,
    ) else {
        return;
    };

    const TILE_BYTES: usize = 16_384 * 4;
    let mut dst_tile = vec![0u8; TILE_BYTES.min(rgba.len())];
    for chunk in rgba.chunks_mut(TILE_BYTES) {
        let out_slice = &mut dst_tile[..chunk.len()];
        transform.transform_pixels(chunk, out_slice);
        for (src_px, dst_px) in chunk.chunks_exact_mut(4).zip(out_slice.chunks_exact(4)) {
            let alpha = src_px[3];
            src_px[0] = dst_px[0];
            src_px[1] = dst_px[1];
            src_px[2] = dst_px[2];
            src_px[3] = alpha;
        }
    }
}

/// Internal helper that decodes an `ImageReader`, validates PSD dimension bounds,
/// converts any embedded RGB ICC profile to sRGB, and composites over white.
fn decode_normalized_srgb_image<R: BufRead + Seek>(
    reader: image::ImageReader<R>,
) -> Result<(u32, u32, Vec<u8>), AppError> {
    let mut decoder = reader
        .into_decoder()
        .map_err(|e| AppError::ImageOpenError(e.to_string()))?;

    let (width, height) = decoder.dimensions();
    if width == 0
        || height == 0
        || width > crate::psd::PSD_MAX_DIMENSION
        || height > crate::psd::PSD_MAX_DIMENSION
    {
        return Err(AppError::InvalidImageDimensions(width, height));
    }

    let embedded_icc = decoder.icc_profile().ok().flatten();
    let dyn_img = image::DynamicImage::from_decoder(decoder)
        .map_err(|e| AppError::ImageOpenError(e.to_string()))?;
    let mut rgba = dyn_img.to_rgba8().into_raw();

    if let Some(icc_bytes) = embedded_icc.as_deref() {
        convert_embedded_icc_to_srgb(&mut rgba, icc_bytes);
    }

    composite_over_white(&mut rgba);

    Ok((width, height, rgba))
}

/// Validates image dimensions against the PSD specification limit (`1..=30_000`),
/// decodes the image from disk, normalizes any embedded RGB ICC profile to sRGB, and composites
/// transparent pixels over opaque white.
#[allow(dead_code)]
pub fn load_normalized_srgb_image(input_path: &str) -> Result<(u32, u32, Vec<u8>), AppError> {
    let reader = image::ImageReader::open(input_path)
        .map_err(|e| AppError::ImageOpenError(e.to_string()))?
        .with_guessed_format()
        .map_err(|e| AppError::ImageOpenError(e.to_string()))?;

    decode_normalized_srgb_image(reader)
}

/// Validates image dimensions against the PSD specification limit (`1..=30_000`),
/// decodes the image from an in-memory byte slice, normalizes any embedded RGB ICC profile to sRGB,
/// and composites transparent pixels over opaque white.
#[allow(dead_code)]
pub fn load_normalized_srgb_image_from_memory(
    bytes: &[u8],
) -> Result<(u32, u32, Vec<u8>), AppError> {
    let reader = image::ImageReader::new(Cursor::new(bytes))
        .with_guessed_format()
        .map_err(|e| AppError::ImageOpenError(e.to_string()))?;

    decode_normalized_srgb_image(reader)
}

/// Downscales decoded sRGB RGBA pixels if necessary to build a `CachedImage` for interactive previews.
fn build_preview_cached_image(
    display_path: &str,
    width: u32,
    height: u32,
    rgba_pixels: Vec<u8>,
) -> Result<CachedImage, AppError> {
    let (out_width, out_height, out_rgba) = if width.max(height) > PREVIEW_MAX_DIMENSION {
        let rgba_img = image::RgbaImage::from_raw(width, height, rgba_pixels).ok_or_else(|| {
            AppError::ImageOpenError("RGBAバッファの構築に失敗しました".to_string())
        })?;
        let resized = image::DynamicImage::ImageRgba8(rgba_img).resize(
            PREVIEW_MAX_DIMENSION,
            PREVIEW_MAX_DIMENSION,
            image::imageops::FilterType::Lanczos3,
        );
        (
            resized.width() as usize,
            resized.height() as usize,
            resized.to_rgba8().into_raw(),
        )
    } else {
        (width as usize, height as usize, rgba_pixels)
    };

    Ok(CachedImage {
        path: display_path.to_string(),
        width: out_width,
        height: out_height,
        rgba: Arc::new(out_rgba),
    })
}

/// Loads, normalizes (embedded ICC -> sRGB + white background composite), and downscales
/// the source image from disk for interactive preview generation.
#[allow(dead_code)]
pub fn load_preview_source(input_path: &str) -> Result<CachedImage, AppError> {
    let (width, height, rgba_pixels) = load_normalized_srgb_image(input_path)?;
    build_preview_cached_image(input_path, width, height, rgba_pixels)
}

/// Loads, normalizes (embedded ICC -> sRGB + white background composite), and downscales
/// an in-memory source image for interactive preview generation.
#[allow(dead_code)]
pub fn load_preview_source_from_memory(
    display_path: &str,
    bytes: &[u8],
) -> Result<CachedImage, AppError> {
    let (width, height, rgba_pixels) = load_normalized_srgb_image_from_memory(bytes)?;
    build_preview_cached_image(display_path, width, height, rgba_pixels)
}

/// Validates a target CMYK ICC color profile from an in-memory byte vector.
pub fn load_cmyk_icc_from_bytes(
    display_path: &str,
    icc_data: Vec<u8>,
) -> Result<CachedIcc, AppError> {
    let cmyk_profile = lcms2::Profile::new_icc(&icc_data)
        .map_err(|e| AppError::ProfileParseError(e.to_string()))?;

    if cmyk_profile.color_space() != lcms2::ColorSpaceSignature::CmykData {
        return Err(AppError::NotCmykProfile);
    }

    Ok(CachedIcc {
        path: display_path.to_string(),
        bytes: Arc::new(icc_data),
    })
}

/// Reads and validates a target CMYK ICC color profile from disk.
#[allow(dead_code)]
pub fn load_cmyk_icc(icc_path: &str) -> Result<CachedIcc, AppError> {
    let icc_data =
        std::fs::read(icc_path).map_err(|e| AppError::ProfileReadError(e.to_string()))?;
    load_cmyk_icc_from_bytes(icc_path, icc_data)
}

/// Converts an interleaved sRGB RGBA8 buffer into interleaved 8-bit CMYK pixels using
/// the target CMYK ICC profile, rendering intent, and Black Point Compensation flag.
pub fn convert_srgb_to_cmyk(
    rgba_pixels: &[u8],
    width: usize,
    height: usize,
    icc: &CachedIcc,
    intent: RenderingIntent,
    black_point_compensation: bool,
) -> Result<Vec<u8>, AppError> {
    let cmyk_profile = lcms2::Profile::new_icc(&icc.bytes)
        .map_err(|e| AppError::ProfileParseError(e.to_string()))?;

    if cmyk_profile.color_space() != lcms2::ColorSpaceSignature::CmykData {
        return Err(AppError::NotCmykProfile);
    }

    let srgb_profile = lcms2::Profile::new_srgb();
    let forward_flags = cmm_transform_flags(black_point_compensation);

    let t_rgb_to_cmyk = lcms2::Transform::new_flags_context(
        lcms2::GlobalContext::new(),
        &srgb_profile,
        lcms2::PixelFormat::RGBA_8,
        &cmyk_profile,
        lcms2::PixelFormat::CMYK_8,
        intent.to_lcms2(),
        forward_flags,
    )
    .map_err(|e| AppError::TransformCreationError(e.to_string()))?;

    let pixel_count = width * height;
    let mut cmyk_pixels = vec![0u8; pixel_count * 4];

    #[cfg(not(target_arch = "wasm32"))]
    {
        let parallelism = std::thread::available_parallelism()
            .map(|n| n.get())
            .unwrap_or(1);

        if parallelism > 1 && pixel_count >= 32_768 {
            let pixels_per_worker = pixel_count.div_ceil(parallelism);
            let bytes_per_worker = pixels_per_worker * 4;
            std::thread::scope(|s| {
                for (src_chunk, dst_chunk) in rgba_pixels
                    .chunks(bytes_per_worker)
                    .zip(cmyk_pixels.chunks_mut(bytes_per_worker))
                {
                    let transform = &t_rgb_to_cmyk;
                    s.spawn(move || {
                        transform.transform_pixels(src_chunk, dst_chunk);
                    });
                }
            });
        } else {
            t_rgb_to_cmyk.transform_pixels(rgba_pixels, &mut cmyk_pixels);
        }
    }

    #[cfg(target_arch = "wasm32")]
    {
        t_rgb_to_cmyk.transform_pixels(rgba_pixels, &mut cmyk_pixels);
    }

    Ok(cmyk_pixels)
}

/// Applies image adjustments in sRGB space and generates soft-proofed CMYK previews
/// for the requested subset of rendering intents using cached source buffers.
pub fn render_intent_previews(
    source: &CachedImage,
    icc: &CachedIcc,
    adjustments: AdjustmentParams,
    black_point_compensation: bool,
    intents: &[RenderingIntent],
) -> Result<Vec<(RenderingIntent, RawPreview)>, AppError> {
    let width = source.width;
    let height = source.height;

    // Apply tone and HSV adjustments prior to forward RGB -> CMYK ICC translation
    let adjusted_rgba = apply_adjustments(&source.rgba, width, height, adjustments);

    let cmyk_profile = lcms2::Profile::new_icc(&icc.bytes)
        .map_err(|e| AppError::ProfileParseError(e.to_string()))?;

    if cmyk_profile.color_space() != lcms2::ColorSpaceSignature::CmykData {
        return Err(AppError::NotCmykProfile);
    }

    let srgb_profile = lcms2::Profile::new_srgb();

    // Proofing transform (CMYK -> sRGB) enforces RelativeColorimetric with Black Point Compensation
    // so paper white maps to display white (255) and CMYK rich black maps cleanly to display black,
    // matching Krita's default display color management when viewing a CMYK PSD.
    let t_cmyk_to_rgb = lcms2::Transform::new_flags_context(
        lcms2::GlobalContext::new(),
        &cmyk_profile,
        lcms2::PixelFormat::CMYK_8,
        &srgb_profile,
        lcms2::PixelFormat::RGBA_8,
        lcms2::Intent::RelativeColorimetric,
        lcms2::Flags::NO_CACHE
            | lcms2::Flags::HIGHRES_PRECALC
            | lcms2::Flags::BLACKPOINT_COMPENSATION,
    )
    .map_err(|e| AppError::TransformCreationError(e.to_string()))?;

    let forward_flags = cmm_transform_flags(black_point_compensation);
    let mut rendered = Vec::with_capacity(intents.len());

    for &intent_enum in intents {
        let t_rgb_to_cmyk = lcms2::Transform::new_flags_context(
            lcms2::GlobalContext::new(),
            &srgb_profile,
            lcms2::PixelFormat::RGBA_8,
            &cmyk_profile,
            lcms2::PixelFormat::CMYK_8,
            intent_enum.to_lcms2(),
            forward_flags,
        )
        .map_err(|e| AppError::TransformCreationError(e.to_string()))?;

        let preview_rgba = soft_proof_pixels(
            &adjusted_rgba,
            width * height,
            &t_rgb_to_cmyk,
            &t_cmyk_to_rgb,
        );

        rendered.push((
            intent_enum,
            RawPreview {
                width,
                height,
                rgba: preview_rgba,
            },
        ));
    }

    Ok(rendered)
}

/// Executes forward (sRGB -> CMYK) and proofing (CMYK -> sRGB) transforms across CPU cores
/// in cache-friendly chunks while restoring opaque alpha bytes (`255`).
fn soft_proof_pixels(
    src_rgba: &[u8],
    pixel_count: usize,
    t_rgb_to_cmyk: &lcms2::Transform<u8, u8, lcms2::GlobalContext, lcms2::DisallowCache>,
    t_cmyk_to_rgb: &lcms2::Transform<u8, u8, lcms2::GlobalContext, lcms2::DisallowCache>,
) -> Vec<u8> {
    let mut preview_rgba = vec![0u8; pixel_count * 4];

    let process_chunk = |src_chunk: &[u8], dst_chunk: &mut [u8]| {
        const L2_TILE_BYTES: usize = 16_384 * 4;
        let mut cmyk_tile = vec![0u8; L2_TILE_BYTES.min(src_chunk.len())];

        for (s_tile, d_tile) in src_chunk
            .chunks(L2_TILE_BYTES)
            .zip(dst_chunk.chunks_mut(L2_TILE_BYTES))
        {
            let cmyk_slice = &mut cmyk_tile[..s_tile.len()];
            t_rgb_to_cmyk.transform_pixels(s_tile, cmyk_slice);
            t_cmyk_to_rgb.transform_pixels(cmyk_slice, d_tile);

            // CMYK lacks an alpha channel. We ensure the output RGBA alpha byte is 255 (100% opaque).
            for px in d_tile.chunks_exact_mut(4) {
                px[3] = 255;
            }
        }
    };

    #[cfg(not(target_arch = "wasm32"))]
    {
        let parallelism = std::thread::available_parallelism()
            .map(|n| n.get())
            .unwrap_or(1);

        if parallelism > 1 && pixel_count >= 32_768 {
            let pixels_per_worker = pixel_count.div_ceil(parallelism);
            let bytes_per_worker = pixels_per_worker * 4;

            std::thread::scope(|s| {
                for (src_chunk, dst_chunk) in src_rgba
                    .chunks(bytes_per_worker)
                    .zip(preview_rgba.chunks_mut(bytes_per_worker))
                {
                    s.spawn(move || {
                        process_chunk(src_chunk, dst_chunk);
                    });
                }
            });
        } else {
            process_chunk(src_rgba, &mut preview_rgba);
        }
    }

    #[cfg(target_arch = "wasm32")]
    {
        process_chunk(src_rgba, &mut preview_rgba);
    }

    preview_rgba
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_composite_over_white_handles_transparent_and_semitransparent_pixels() {
        let mut rgba = vec![
            0, 0, 0, 0, // Fully transparent black -> opaque white
            0, 0, 0, 128, // ~50% transparent black -> mid gray
            200, 100, 50, 255, // Fully opaque -> unchanged
        ];
        composite_over_white(&mut rgba);

        assert_eq!(&rgba[0..4], &[255, 255, 255, 255]);
        assert_eq!(&rgba[4..8], &[127, 127, 127, 255]);
        assert_eq!(&rgba[8..12], &[200, 100, 50, 255]);
    }

    #[test]
    fn test_render_intent_previews_with_japan_color_icc() {
        if !std::path::Path::new("JapanColor2001Coated.icc").exists() {
            return;
        }
        let icc = load_cmyk_icc("JapanColor2001Coated.icc")
            .expect("JapanColor2001Coated.icc should load and validate as CMYK");
        let src = CachedImage {
            path: "synthetic.png".to_string(),
            width: 32,
            height: 32,
            rgba: Arc::new(vec![180, 90, 220, 255].repeat(32 * 32)),
        };

        let base = render_intent_previews(
            &src,
            &icc,
            AdjustmentParams::default(),
            true,
            &[RenderingIntent::Perceptual],
        )
        .expect("Base soft-proof preview should succeed");

        let adjusted = render_intent_previews(
            &src,
            &icc,
            AdjustmentParams {
                hue: -20,
                saturation: 30,
                value: 10,
                contrast: 15,
                highlights: -10,
                shadows: 25,
            },
            true,
            &RenderingIntent::ALL,
        )
        .expect("Adjusted soft-proof preview across all intents should succeed");

        assert_eq!(base.len(), 1);
        assert_eq!(adjusted.len(), 4);
        assert_ne!(base[0].1.rgba, adjusted[0].1.rgba);
        assert!(adjusted[0].1.rgba.chunks_exact(4).all(|px| px[3] == 255));
    }

    #[test]
    fn test_black_point_compensation_flag_on_relative_intent() {
        if !std::path::Path::new("JapanColor2001Coated.icc").exists() {
            return;
        }
        let icc = load_cmyk_icc("JapanColor2001Coated.icc")
            .expect("JapanColor2001Coated.icc should load and validate as CMYK");
        let mut pixels = Vec::with_capacity(64 * 4);
        for v in 0..64u8 {
            pixels.extend_from_slice(&[v, v, v, 255]);
        }
        let src = CachedImage {
            path: "shadow_ramp.png".to_string(),
            width: 8,
            height: 8,
            rgba: Arc::new(pixels),
        };

        let with_bpc = render_intent_previews(
            &src,
            &icc,
            AdjustmentParams::default(),
            true,
            &[RenderingIntent::Relative],
        )
        .expect("Relative preview with BPC should succeed");

        let without_bpc = render_intent_previews(
            &src,
            &icc,
            AdjustmentParams::default(),
            false,
            &[RenderingIntent::Relative],
        )
        .expect("Relative preview without BPC should succeed");

        assert_ne!(
            with_bpc[0].1.rgba, without_bpc[0].1.rgba,
            "Black Point Compensation should alter deep shadow mapping under Relative Colorimetric"
        );
    }
}
